pages.css:
.hero{padding:96px 0 72px;background:radial-gradient(circle at 80% 20%,rgba(27,80,57,.55),transparent 60%)}
.hero h1{max-width:18ch;margin:16px 0;font-size:clamp(2.2rem,5vw,4rem);line-height:1.05;color:var(--ink)}
.lede{max-width:60ch;color:var(--muted);font-size:1.15rem;line-height:1.6}
.actions{display:flex;flex-wrap:wrap;gap:12px;margin-top:28px}
.cards{padding-top:56px}.cards h2,.compare h2{color:var(--ink);font-size:clamp(1.6rem,3vw,2.2rem)}
.cards ul{display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:20px;padding:0;list-style:none}
.cards li{padding:24px;border:1px solid var(--line);border-radius:16px;background:rgba(255,255,255,.03)}
.cards h3{margin:0 0 8px;color:var(--lime)}.cards p{margin:0;color:var(--muted);line-height:1.55}
.compare{padding-top:56px}.compare table{width:100%;border-collapse:collapse;color:var(--ink)}
.compare th,.compare td{padding:14px 12px;border-bottom:1px solid var(--line);text-align:left}
.enquire{padding-top:40px}
body ~ footer{display:none}
